#include <bits/stdc++.h>
using namespace std;

const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;
const int INF = 0x3f3f3f3f;

char grid1[MAXN][MAXN], grid2[MAXN][MAXN];
int timeInfected[MAXN][MAXN];
int N, T;
int dirX[4] = {1, 0, -1, 0};
int dirY[4] = {0, 1, 0, -1};

inline bool isWalk(char c) { return c >= '0' && c <= '9'; }
inline bool isNum(char c) { return c >= '1' && c <= '9'; }

struct Dinic {
    vector<int> adj[MAXV];
    int cap[MAXV * MAXV];
    int dist[MAXV];
    bool vis[MAXV];

    Dinic() { memset(cap, 0, sizeof(cap)); }

    inline int &edgeCap(int u, int v) {
        return cap[u * MAXV + v];
    }

    void addEdge(int u, int v, int c) {
        adj[u].push_back(v);
        adj[v].push_back(u);
        edgeCap(u, v) = c;
        edgeCap(v, u) = 0;
    }

    bool bfs(int s, int t) {
        memset(dist, -1, sizeof(dist));
        queue<int> q;
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : adj[u]) {
                if (edgeCap(u, v) > 0 && dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
        }
        return dist[t] != -1;
    }

    int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        vis[u] = true;
        for (int v : adj[u]) {
            if (edgeCap(u, v) > 0 && !vis[v] && dist[v] == dist[u] + 1) {
                int got = dfs(v, t, min(flow, edgeCap(u, v)));
                if (got > 0) {
                    edgeCap(u, v) -= got;
                    edgeCap(v, u) += got;
                    return got;
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int ans = 0;
        while (bfs(s, t)) {
            memset(vis, 0, sizeof(vis));
            int got;
            while ((got = dfs(s, t, INF)) > 0) ans += got;
        }
        return ans;
    }
};

Dinic dinic;

void infectedBFS(int sx, int sy) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            timeInfected[i][j] = INF;
    timeInfected[sx][sy] = 0;
    queue<pair<int,int>> q;
    q.push(make_pair(sx, sy));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dirX[d], ny = y + dirY[d];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
            if (isWalk(grid1[nx][ny]) && timeInfected[nx][ny] == INF) {
                timeInfected[nx][ny] = timeInfected[x][y] + 1;
                q.push(make_pair(nx, ny));
            }
        }
    }
}

void createEdges(int sx, int sy) {
    int d[MAXN][MAXN];
    memset(d, INF, sizeof(d));
    d[sx][sy] = 0;
    if (isNum(grid2[sx][sy]))
        dinic.addEdge(N * sx + sy, N * N + N * sx + sy, INF);

    queue<pair<int,int>> q;
    q.push(make_pair(sx, sy));
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dirX[k], ny = y + dirY[k];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N) continue;
            if (d[nx][ny] != INF) continue;
            if (!isWalk(grid1[nx][ny])) continue;
            int nd = d[x][y] + 1;
            if (nd <= min(timeInfected[nx][ny] - 1, T)) {
                d[nx][ny] = nd;
                q.push(make_pair(nx, ny));
            }
            if (nd <= min(timeInfected[nx][ny], T) && isNum(grid2[nx][ny]))
                dinic.addEdge(N * sx + sy, N * N + N * nx + ny, INF);
        }
    }
}

int main() {
    scanf("%d%d", &N, &T);
    int zx = 0, zy = 0;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &grid1[i][j]);
            if (grid1[i][j] == 'Z') {
                zx = i; zy = j;
            } else if (isNum(grid1[i][j])) {
                dinic.addEdge(MAXV - 2, i * N + j, grid1[i][j] - '0');
            }
        }
    }

    infectedBFS(zx, zy);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf(" %c", &grid2[i][j]);
            if (isNum(grid2[i][j]))
                dinic.addEdge(N * N + i * N + j, MAXV - 1, grid2[i][j] - '0');
        }
    }

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (isNum(grid1[i][j])) createEdges(i, j);

    printf("%d\n", dinic.maxFlow(MAXV - 2, MAXV - 1));
    return 0;
}
